#!/usr/bin/env node
/**
 * Generate the adversarial review extract: a single markdown file for readers with no project
 * history, from a FIXED sample list.
 *
 * WHY DETERMINISTIC AND WHY THE LIST IS COMMITTED. A one-off extract makes its own review
 * unrepeatable: a reviewer's objection cannot be checked against what they actually read, and a
 * later run with a different draw would answer a different question. `review/extract-sample.json`
 * holds the sample, this file holds the transformation, and both are committed, so the extract can
 * be regenerated byte-for-byte and the review re-run against a changed corpus.
 *
 * WHAT IS STRIPPED, AND WHY IT MATTERS THAT THE LIST IS EXPLICIT. The point of the exercise is to
 * learn what a reader objects to WITHOUT knowing what this project considers acceptable. So the
 * extract carries no record ids, no cross-references, no enum tokens, no lens or domain names, no
 * rule numbers, and no CLAUDE.md. Scores are rendered as plain English rather than as the
 * vocabulary the schema uses, because the enum token is itself a claim about the framework.
 *
 * WHAT IS DELIBERATELY KEPT. Source tiers, because a reviewer cannot judge sourcing without them,
 * and the methodology note says what they mean. And the caveats, which are where this corpus does
 * most of its hedging — a review that never sees them would be attacking a straw version.
 *
 * The transformation is lossy and the extract SAYS SO. A reviewer told that text was processed can
 * discount accordingly; one who is not told cannot.
 *
 * Usage:  node tools/gen-review-extract.mjs   ·   npm run review-extract
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SAMPLE = join(ROOT, 'review', 'extract-sample.json');
const OUT = join(ROOT, 'review', 'adversarial-extract.md');

/** Plain-English renderings. The enum token never reaches the reader. */
const SCORE = {
  worked: 'The project judges that this achieved what it set out to do.',
  partly: 'The project judges this a split: part of it delivered, part cannot be scored.',
  failed: 'The project judges that this did not achieve what it set out to do.',
  reversed: 'The project judges that this was undone.',
  contested: 'The project declines to score this, holding that the two sides argue past each other.',
  'too-early': 'The project judges it too early to say; the obstacle is elapsed time.',
  'awaiting-adjudication': 'The project judges this unresolved pending a decision by a body outside the parties.',
  'no-objective': 'The project judges that no target was announced against which this could have succeeded or failed.',
  'baseline-context': 'Recorded as background rather than scored.',
};

const REASON = {
  'not-collected': 'the figure was never gathered by anyone',
  'not-published': 'the figure exists in some body’s hands but has not been released',
  withheld: 'release was specifically requested and refused',
  'never-defined': 'no agreed definition of the quantity exists, so it could not be collected even in principle',
};

/**
 * Remove the internal framework from prose.
 *
 * Cross-references become a neutral phrase rather than being deleted, because deleting them leaves
 * sentences that read as though a comparison were being made to nothing.
 */
function scrub(s) {
  if (typeof s !== 'string') return '';
  let t = s;
  t = t.replace(/\b(?:L-\d{4}|P-\d{2,4}|PR-\d{2,4})\b/g, 'another record in this corpus');
  t = t.replace(/\b(?:recorded at|see|cf\.?|per)\s+another record in this corpus/gi, 'another record in this corpus');
  t = t.replace(/\bcommitment state \([a-d]\)\s*[—-]?\s*/gi, '');
  t = t.replace(/\bstate \([a-d]\)\b/gi, 'that state');
  t = t.replace(/\brules? \d+[a-z]?\b/gi, 'a standing rule of this project');
  t = t.replace(/\bstop condition \d+\b/gi, 'a standing stop condition');
  t = t.replace(/\bdifferentFacts\b/g, 'competing-accounts');
  t = t.replace(/\b(?:M1|M2)\b/g, 'a verification step');
  t = t.replace(/\breasonKind\b/g, 'the stated reason');
  t = t.replace(/\bphase \d+\b/gi, 'an earlier phase');
  t = t.replace(/\bthis phase(?:'s)?\b/gi, 'this stage of the work');

  // Score and reason tokens leak through prose as well as through the fields. The token IS the
  // framework, so it is replaced wherever it appears and not only where it is rendered.
  const TOKENS = [
    [/\bno-objective\b/gi, 'unscoreable for want of a stated target'],
    [/\btoo-early\b/gi, 'too early to say'],
    [/\bawaiting-adjudication\b/g, 'pending an outside decision'],
    [/\bbaseline-context\b/g, 'background rather than scored'],
    [/\bnot-published\b/g, 'held but unreleased'],
    [/\bnot-collected\b/g, 'never gathered'],
    [/\bnever-defined\b/g, 'undefinable as a quantity'],
    [/\bcompeting-accounts\b/g, 'competing accounts'],
  ];
  for (const [re_, to] of TOKENS) t = t.replace(re_, to);

  // Internal maintenance annotations. These are administration of the framework — bulk rescoring
  // passes, schema decisions, this sweep's own correction cycles — and they describe the project's
  // housekeeping rather than the subject. Removed whole-sentence, because a half-removed annotation
  // reads as a claim about the world.
  // Terminates on a sentence end OR on end-of-string: these annotations are often appended to a
  // source name, which carries no closing full stop.
  const ADMIN = /(?:^|(?<=[.;]\s))[^.;]*\b(?:RESCORED|VALUE-AND-NOTE RECONCILED|No new enum value|enum|schema|validator|DEEP-LINKED \d{4}|CORRECTED \d{4}|correction cycle \d|the contested sink)\b[^.;]*(?:[.;]\s*|$)/g;
  // Dated housekeeping HEADERS appended to a source name, e.g. "DEEP-LINKED 2026-08-05 (correction
  // cycle 8): ...". Only the header is removed. What follows it is usually the evidence for an
  // identification — which figures were matched against which retrieved document — and a reviewer
  // should see that; it is the difference between a citation improved on evidence and one improved
  // on assertion.
  t = t.replace(/\b(?:DEEP-LINKED|CORRECTED|RESCORED|IDENTIFIED AND UPGRADED(?: FROM T\d)?)\s+\d{4}-\d{2}-\d{2}\s*(?:\([^)]*\))?\s*:?\s*/g, '');

  let prev;
  do { prev = t; t = t.replace(ADMIN, ''); } while (t !== prev);

  t = t.replace(/ {2,}/g, ' ').replace(/\s+([,.;:])/g, '$1');
  return t.trim();
}

const para = (label, body) => (body && body.trim() ? `**${label}.** ${body}\n\n` : '');

function ledger() {
  const out = new Map();
  const dir = join(ROOT, 'data', 'ledger');
  for (const f of readdirSync(dir).filter((x) => x.endsWith('.json'))) {
    for (const r of JSON.parse(readFileSync(join(dir, f), 'utf8'))) out.set(r.id, r);
  }
  return out;
}

const sample = JSON.parse(readFileSync(SAMPLE, 'utf8'));
const recs = ledger();

const parts = [];
parts.push('# Extract for external review\n');
// Counted, never written by hand. The first version hard-coded "Thirty-four" and the sample later
// grew to 38, so the document opened by misdescribing itself — and a reviewer who counts is
// entitled to distrust everything after that.
const N_RECORDS = sample.records.filter((s) => recs.has(s.id)).length;
const N_NORECORD = sample.no_record_outcomes.length;
parts.push(
  `${N_RECORDS} records from a longitudinal research corpus about Indian government policy, plus ` +
    `${N_NORECORD} subjects the project examined and decided **not** to record. Presented for adversarial ` +
    'review: the question is what a reader objects to, in the reasoning, the sourcing, the framing, ' +
    'or the decision to record at all.\n',
);

parts.push('## How to read this, and what has been done to it\n');
parts.push(
  'This text has been **processed**, and a reviewer should discount accordingly. Record ' +
    'identifiers, cross-references between records, internal category names and rule numbers have ' +
    'been removed or replaced with neutral phrases, so that the framework the project uses is not ' +
    'visible and cannot be deferred to. Where a record referred to another by identifier, the ' +
    'reference now reads "another record in this corpus" — the comparison was real, its target is ' +
    'not shown.\n\n' +
    'Scores are rendered as sentences rather than as the vocabulary the project files them under. ' +
    'The project’s own rulebook is deliberately **not** included: the point is what you object ' +
    'to without knowing what it considers acceptable.\n\n' +
    '**Source tiers are kept**, because sourcing cannot be judged without them — but read the rule ' +
    'before the ladder. The tier grades **the document actually held, not the institution the ' +
    'subject belongs to**: a national auditor’s finding known only through a newspaper’s account of ' +
    'it is T4, because the subject is official and the evidence is relayed. Grade what you hold, ' +
    'not what it is about. On that rule: T1 an official Indian statistical or institutional source ' +
    'retrieved directly — a ministry release, a central-bank or statistics-office publication, an ' +
    'audit report, a parliamentary reply; T2 a multilateral or international statistical source ' +
    'retrieved directly; T3 peer-reviewed research or a working paper; T4 journalism, NGO datasets, ' +
    'and anything relayed rather than retrieved, including an official figure known only through a ' +
    'press account; T5 a contested composite index.\n\n' +
    'Two consequences a reviewer should hold the project to. A tier can move when the evidence ' +
    'moves and not otherwise — a paper cited from a search summary sits at T4 and rises only when ' +
    'the paper is opened. And a domestic statutory body is T1, not T2; T2 is for international ' +
    'sources, so provenance and strength are not the same ladder.\n\n' +
    '**Caveats are kept in full.** They are where this corpus does most of its hedging, and a ' +
    'review that never saw them would be attacking something weaker than the real thing.\n',
);

parts.push('## Method, offered for attack\n');
parts.push(
  'The corpus records discrete government actions and asks, of each, what was claimed at the ' +
    'outset and what can be established since. Four commitments are worth stating because they ' +
    'are the method’s load-bearing choices, and each can be argued with:\n\n' +
    '1. **A source that could not be retrieved is not cited as though it had been.** Where a ' +
    'document was described from a secondary account, the record says so and is tiered down.\n' +
    '2. **Where two instruments measure the same quantity and disagree, neither figure is adopted ' +
    'and no midpoint is taken.** The disagreement is recorded as the finding.\n' +
    '3. **An absence is recorded only when the place it would appear was checked.** The record ' +
    'states which document was searched and what else that document does contain.\n' +
    '4. **Every record carries a case for and a case against**, and the project holds that a record ' +
    'presenting only one is defective regardless of which side it favours.\n\n' +
    'Objections to any of these are more useful than objections to individual figures.\n',
);

parts.push('---\n');
parts.push('## Records\n');

let n = 0;
for (const { id } of sample.records) {
  const r = recs.get(id);
  if (!r) continue;
  n += 1;
  parts.push(`### ${n}. ${scrub(r.title)}\n`);
  parts.push(`*Dated ${r.date}.*\n\n`);
  parts.push(para('What this is', scrub(r.summary)));
  parts.push(para('What was claimed at the outset', scrub(r.claimAtLaunch)));
  parts.push(para('What can be established since', scrub(r.whatHappened)));
  parts.push(para('The case for', scrub(r.caseFor)));
  parts.push(para('The case against', scrub(r.caseAgainst)));
  const verdict = SCORE[r.assessment] ?? '';
  parts.push(para('Verdict', `${verdict} ${scrub(r.assessmentNote)}`.trim()));
  if (r.differentFactsNote) parts.push(para('On the competing accounts', scrub(r.differentFactsNote)));
  for (const u of r.unmeasured ?? []) {
    parts.push(
      para(
        'Not measured',
        `${scrub(u.what)} — ${scrub(u.why)} The stated reason is that ${REASON[u.reasonKind] ?? 'it is unavailable'}.` +
          (u.wouldFill ? ` What would settle it: ${scrub(u.wouldFill)}` : ''),
      ),
    );
  }
  parts.push(para('Caveat', scrub(r.caveat)));
  if (r.sources?.length) {
    parts.push('**Sources.**\n\n');
    for (const s of r.sources) parts.push(`- *(${s.tier ?? 'untiered'})* ${scrub(s.name)}\n`);
    parts.push('\n');
  }
  parts.push('---\n');
}

parts.push('## Subjects examined and deliberately not recorded\n');
parts.push(
  'The project treats a decision not to record as a result rather than a gap. Three are described ' +
    'here so the decision itself can be argued with. No record exists for any of them.\n\n',
);
const NO_RECORD = {
  'Bangladesh, first pass':
    'The subject was a power-purchase arrangement and its unpaid dues. Two secondary accounts gave ' +
    'incompatible figures for the same quantity — one reporting the sum cleared in full, the ' +
    'other an amount outstanding — and no primary document was retrieved. The project declined ' +
    'to record rather than pick a figure or split the difference. It later opened the subject from a ' +
    'different ministry’s publications, where a measured series existed.',
  'Sri Lanka, first pass':
    'The foreign ministry’s website returns a page containing no document text, and a second ' +
    'government route carried nothing current. The project declined to record. The subject was ' +
    'opened later through a third route — the prime minister’s office — which the ' +
    'project had not previously treated as a source of substantive bilateral detail.',
  'UN Security Council advocacy':
    'India’s campaign for permanent membership is long-standing and widely reported. The ' +
    'project found no retrieved primary stating it as a commitment with any trigger, date or ' +
    'condition attached, and declined to record it. Its stated reason: a record written from no ' +
    'primary source would document the search rather than the world.',
};
for (const nr of sample.no_record_outcomes) {
  parts.push(`### ${nr.subject}\n\n${NO_RECORD[nr.subject] ?? ''}\n\n`);
}

parts.push('---\n');
parts.push('## What the project would most like challenged\n');
parts.push(
  'Not the arithmetic, which is checked mechanically. The judgement calls: whether a refusal to ' +
    'score is ever a way of avoiding a conclusion the evidence supports; whether the case-for ' +
    'sections are as strong as the case-against sections or merely present; whether recording an ' +
    'absence as a finding inflates the significance of ordinary administrative silence; and ' +
    'whether the set below reads as one-directional despite containing records whose findings run ' +
    'in the government’s favour.\n',
);

const body = parts.join('');

// The declared total must equal the numbered headings actually emitted. A document that
// misdescribes its own size invites a reviewer to discount everything else in it.
const headings = (body.match(/^### \d+\. /gm) ?? []).length;
if (headings !== N_RECORDS) {
  console.error(`gen-review-extract FAILED — declares ${N_RECORDS} records but emitted ${headings} numbered headings`);
  process.exit(1);
}
if (!body.startsWith(`# Extract for external review\n${N_RECORDS} records`)) {
  console.error(`gen-review-extract FAILED — the opening line does not state ${N_RECORDS} records`);
  process.exit(1);
}
writeFileSync(OUT, body);
console.log(
  `review extract OK — ${n} records + ${sample.no_record_outcomes.length} no-record subjects, ` +
    `${Buffer.byteLength(body).toLocaleString()} bytes, ${body.split('\n').length.toLocaleString()} lines -> ${OUT.replace(`${ROOT}/`, '')}`,
);
